export class Icd10TaxonomyService {
  public static findByCode(code: string): MasterTaxonomyDiagnosis | undefined {
    return ICD10_COMPREHENSIVE_REGISTRY.find((d) => d.code === code.toUpperCase().trim());
  }

  public static searchByTerm(term: string): MasterTaxonomyDiagnosis[] {
    const q = term.toLowerCase();
    return ICD10_COMPREHENSIVE_REGISTRY.filter(
      (d) => d.code.toLowerCase().includes(q) || d.shortDesc.toLowerCase().includes(q) || d.longDesc.toLowerCase().includes(q)
    );
  }
}
